[CmdletBinding(SupportsShouldProcess=$true)]
param(
 [ValidateSet('Start','Continue','Status','Summarize','Stop')][string]$Action='Status',
 [ValidateRange(1,20)][int]$RunsPerArm=5,
 [ValidateRange(30,600)][int]$SampleSeconds=120,
 [ValidateRange(1,10)][int]$SampleIntervalSeconds=2,
 [switch]$AllowAutomaticReboot,
 [string]$EvidenceRoot="$PSScriptRoot\lab-evidence",
 [string]$RunDirectory,
 [string]$ProviderPath="$PSScriptRoot\..\..\controller\providers\LogitechGHubSigninTask.ps1"
)
Set-StrictMode -Version 2.0;$ErrorActionPreference='Stop';$Experiment='EXP-091';$TaskName='Lacksan-EXP-091-LabHarness';$ActivePointer=Join-Path $EvidenceRoot 'active.json'
function Elevation{$p=New-Object Security.Principal.WindowsPrincipal([Security.Principal.WindowsIdentity]::GetCurrent());if(!$p.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)){throw 'Elevation required.'}}
function Ensure($p){if(!(Test-Path -LiteralPath $p)){New-Item -ItemType Directory -Path $p -Force|Out-Null}}
function WJ($p,$v){$v|ConvertTo-Json -Depth 20|Set-Content -LiteralPath $p -Encoding UTF8};function RJ($p){if(!(Test-Path -LiteralPath $p)){throw "Required state missing: $p"};Get-Content -LiteralPath $p -Raw|ConvertFrom-Json}
function BootUtc{((Get-CimInstance Win32_OperatingSystem).LastBootUpTime).ToUniversalTime()};function Med($v){$a=@($v|Where-Object{$null-ne$_}|%{[double]$_}|Sort-Object);if(!$a.Count){return $null};$m=[int][math]::Floor($a.Count/2);if($a.Count%2){return $a[$m]};($a[$m-1]+$a[$m])/2};function Mad($v){$a=@($v|Where-Object{$null-ne$_}|%{[double]$_});if(!$a.Count){return $null};$m=Med $a;Med @($a|%{[math]::Abs($_-$m)})}
function Paths($d){[pscustomobject]@{Harness=Join-Path $d 'harness-state.json';Provider=Join-Path $d 'provider-state.json';ProviderLog=Join-Path $d 'provider-events.jsonl';Summary=Join-Path $d 'summary.json'}}
function Dir{if($RunDirectory){return(Resolve-Path -LiteralPath $RunDirectory).Path};$a=RJ $ActivePointer;(Resolve-Path -LiteralPath ([string]$a.runDirectory)).Path}
function Provider($a,$d){$p=Paths $d;& $ProviderPath -Action $a -StatePath $p.Provider -LogPath $p.ProviderLog}
function ResumeTask{Get-ScheduledTask -TaskName $TaskName -ErrorAction SilentlyContinue};function RegisterResume($d){if(ResumeTask){throw 'Continuation task collision.'};$exe=(Get-Command powershell.exe).Source;$args="-NoProfile -ExecutionPolicy Bypass -File `"$PSCommandPath`" -Action Continue -RunDirectory `"$d`" -EvidenceRoot `"$EvidenceRoot`" -ProviderPath `"$ProviderPath`"";$a=New-ScheduledTaskAction -Execute $exe -Argument $args;$u=[Security.Principal.WindowsIdentity]::GetCurrent().Name;$t=New-ScheduledTaskTrigger -AtLogOn -User $u;$pr=New-ScheduledTaskPrincipal -UserId $u -LogonType Interactive -RunLevel Highest;$s=New-ScheduledTaskSettingsSet -AllowStartIfOnBatteries -DontStopIfGoingOnBatteries;if($PSCmdlet.ShouldProcess($TaskName,'Register continuation task')){Register-ScheduledTask -TaskName $TaskName -Action $a -Trigger $t -Principal $pr -Settings $s|Out-Null}}
function RemoveResume{if(ResumeTask){Unregister-ScheduledTask -TaskName $TaskName -Confirm:$false}}
function Protected{$svc=@();foreach($n in 'WinDefend','mpssvc','wuauserv','Tailscale','TermService'){try{$s=Get-Service $n -ErrorAction Stop;$svc+=[pscustomobject]@{name=$n;status="$($s.Status)";startType="$($s.StartType)"}}catch{$svc+=[pscustomobject]@{name=$n;status='absent'}}};[pscustomobject]@{services=$svc;processes=@(Get-Process -ErrorAction SilentlyContinue|?{$_.ProcessName-match'(?i)omnissa|horizon|msrdc|mstsc|tailscale|windowsapp'}|select ProcessName,Id,Responding)}}
function TaskState($ps){$t=Get-ScheduledTask -TaskPath ([string]$ps.task.TaskPath) -TaskName ([string]$ps.task.TaskName) -ErrorAction Stop;[pscustomobject]@{enabled=[bool]$t.Settings.Enabled;path=$t.TaskPath;name=$t.TaskName}}
function Sample($phase,$ordinal,$d,$ps){$boot=BootUtc;$before=[double](Get-Process -Id $PID).TotalProcessorTime.TotalMilliseconds;$sys=@();$count=[int][math]::Ceiling($SampleSeconds/[double]$SampleIntervalSeconds);for($i=0;$i-lt$count;$i++){$c=Get-CimInstance Win32_PerfFormattedData_PerfOS_Processor -Filter "Name='_Total'";$k=Get-CimInstance Win32_PerfFormattedData_PerfDisk_PhysicalDisk -Filter "Name='_Total'";$sys+=[pscustomobject]@{cpu=[double]$c.PercentProcessorTime;disk=[double]$k.DiskBytesPersec};if($i-lt$count-1){Start-Sleep $SampleIntervalSeconds}};$after=[double](Get-Process -Id $PID).TotalProcessorTime.TotalMilliseconds;[ordered]@{schemaVersion=1;experiment=$Experiment;phase=$phase;ordinal=$ordinal;bootUtc=$boot.ToString('o');capturedUtc=(Get-Date).ToUniversalTime().ToString('o');task=TaskState $ps;system=@{cpuMedianPercent=Med @($sys|% cpu);cpuMadPercent=Mad @($sys|% cpu);diskMedianBytesPerSec=Med @($sys|% disk);diskMadBytesPerSec=Mad @($sys|% disk)};ghubProcesses=@(Get-Process -ErrorAction SilentlyContinue|?{$_.ProcessName-match'(?i)^lghub'}|select ProcessName,Id,CPU,WorkingSet64,Responding);protected=Protected;functionalEvidence=@{manualGHubLaunch='needs-evidence';deviceAndProfileReadiness='needs-evidence';supportedUpdateCheck='needs-evidence';protectedApplicationReadiness='needs-evidence'};instrumentation=@{collectorCpuDeltaMs=$after-$before;sampleCount=$sys.Count}}}
function Summary($d){$r=@(Get-ChildItem $d -Filter 'run-*.json' -File|Sort Name|%{RJ $_.FullName});$g=[ordered]@{};foreach($ph in 'Baseline','Treatment'){$x=@($r|? phase -eq $ph);$g[$ph]=@{runs=$x.Count;cpuMedianPercent=@{median=Med @($x|%{$_.system.cpuMedianPercent});mad=Mad @($x|%{$_.system.cpuMedianPercent})};diskMedianBytesPerSec=@{median=Med @($x|%{$_.system.diskMedianBytesPerSec});mad=Mad @($x|%{$_.system.diskMedianBytesPerSec})}}};$o=[ordered]@{schemaVersion=1;experiment=$Experiment;classification='inconclusive';groups=$g;remainingEvidence=@('Manual G Hub launch','Device and profile readiness','Supported G Hub update check','Timed Omnissa Windows App Remote Desktop and Tailscale readiness','Instrumentation qualification');limitations=@('Physical function remains needs-evidence until exercised')};WJ(Join-Path $d 'summary.json')$o;$o}
function Reboot{if($AllowAutomaticReboot){Restart-Computer -Force}else{Write-Output 'Reboot required; continuation resumes at next interactive logon.'}}
Elevation;if(!(Test-Path $ProviderPath)){throw 'EXP-091 provider missing.'};switch($Action){
'Start'{Ensure $EvidenceRoot;Provider Check $EvidenceRoot|Out-Null;Provider DryRun $EvidenceRoot|Out-Null;if($WhatIfPreference){return};$d=Join-Path $EvidenceRoot((Get-Date).ToUniversalTime().ToString('yyyyMMdd-HHmmss'));Ensure $d;$p=Paths $d;Provider Capture $d|Out-Null;WJ $p.Harness @{schemaVersion=1;phase='Baseline';completedRuns=0;runsPerArm=$RunsPerArm;lastBootUtc=$null};WJ $ActivePointer @{runDirectory=$d};RegisterResume $d;Reboot}
'Continue'{$d=Dir;$p=Paths $d;$s=RJ $p.Harness;$ps=RJ $p.Provider;$boot=(BootUtc).ToString('o');if($s.lastBootUtc-eq$boot){throw 'Duplicate same-boot collection refused.'};if($s.phase-eq'RollbackVerify'){Provider Check $d|Out-Null;$t=Sample RollbackVerify 1 $d $ps;WJ(Join-Path $d 'run-RollbackVerify-01.json')$t;Summary $d|Out-Null;RemoveResume;Remove-Item $ActivePointer -Force;return RJ $p.Summary};if($s.phase-eq'Treatment'){Provider VerifyReboot $d|Out-Null};$ord=[int]$s.completedRuns+1;$t=Sample $s.phase $ord $d $ps;WJ(Join-Path $d("run-{0}-{1:d2}.json"-f$s.phase,$ord))$t;$s.completedRuns=$ord;$s.lastBootUtc=$boot;if($ord-ge[int]$s.runsPerArm){if($s.phase-eq'Baseline'){Provider Apply $d|Out-Null;Provider Verify $d|Out-Null;$s.phase='Treatment';$s.completedRuns=0}else{Provider Rollback $d|Out-Null;$s.phase='RollbackVerify';$s.completedRuns=0}};WJ $p.Harness $s;Reboot}
'Status'{$d=Dir;$p=Paths $d;[pscustomobject]@{RunDirectory=$d;Harness=RJ $p.Harness;Provider=RJ $p.Provider;ContinuationTaskPresent=[bool](ResumeTask)}}
'Summarize'{$d=Dir;Summary $d}
'Stop'{$d=Dir;$p=Paths $d;if(Test-Path $p.Provider){try{Provider Rollback $d|Out-Null}catch{}};RemoveResume;if(Test-Path $ActivePointer){Remove-Item $ActivePointer -Force}}
}